package com.hl.findining.review

import com.hl.findining.shared.domain.enums.Sentiment
import com.hl.findining.shared.domain.enums.VisitType
import java.time.Instant
import java.time.LocalDate

/**
 * 리뷰 도메인 엔티티 (API - 외부 모듈에서 접근 가능)
 */
data class Review(
    val id: String? = null,
    val restaurantId: String,

    // 작성자 정보
    val authorName: String,
    val authorSource: ReviewSource = ReviewSource.INTERNAL,

    // 리뷰 내용
    val content: String,
    val rating: Double,                    // 1.0 ~ 5.0
    val visitDate: LocalDate? = null,
    val visitType: VisitType? = null,

    // 이미지
    val images: List<ReviewImage> = emptyList(),

    // AI 분석 결과
    val extractedTags: List<String> = emptyList(),
    val sentiment: Sentiment? = null,
    val sentimentScore: Double? = null,
    val highlights: List<String> = emptyList(),

    // 통계
    val helpfulCount: Int = 0,

    // 메타데이터
    val status: ReviewStatus = ReviewStatus.ACTIVE,
    val isVerified: Boolean = false,
    val createdAt: Instant = Instant.now(),
    val updatedAt: Instant = Instant.now()
) {
    init {
        require(rating in 1.0..5.0) { "Rating must be between 1.0 and 5.0" }
    }

    val isPositive: Boolean get() = sentiment == Sentiment.POSITIVE
    val isNegative: Boolean get() = sentiment == Sentiment.NEGATIVE
    val hasImages: Boolean get() = images.isNotEmpty()
    val hasAiAnalysis: Boolean get() = sentiment != null

    /**
     * 기존 AI 필드들을 ReviewAiAnalysis Value Object로 변환
     * - 새로운 AI 도메인 모델과 하위 호환성 유지
     */
    fun toAiAnalysis(): ReviewAiAnalysis? {
        return ReviewAiAnalysis.fromLegacyFields(
            sentiment = sentiment,
            sentimentScore = sentimentScore,
            extractedTags = extractedTags,
            highlights = highlights
        )
    }

    /**
     * ReviewAiAnalysis를 적용하여 새 Review 인스턴스 반환
     */
    fun withAiAnalysis(analysis: ReviewAiAnalysis): Review {
        return copy(
            extractedTags = analysis.extractedTags.map { it.name },
            sentiment = analysis.sentiment,
            sentimentScore = analysis.sentimentScore,
            highlights = analysis.highlights.map { it.text }
        )
    }

    /**
     * 추출된 태그를 ExtractedReviewTag 타입으로 변환
     */
    fun getExtractedTagsTyped(): List<ExtractedReviewTag> {
        return extractedTags.map { ExtractedReviewTag.fromString(it) }
    }
}

/**
 * 리뷰 이미지
 */
data class ReviewImage(
    val url: String,
    val thumbnailUrl: String? = null,
    val caption: String? = null
)

/**
 * 리뷰 출처
 */
enum class ReviewSource(val displayName: String) {
    INTERNAL("직접 작성"),
    NAVER("네이버"),
    KAKAO("카카오"),
    GOOGLE("구글"),
    INSTAGRAM("인스타그램"),
    MANGOPLATE("망고플레이트")
}

/**
 * 리뷰 상태
 */
enum class ReviewStatus {
    ACTIVE,
    HIDDEN,
    DELETED,
    PENDING
}

package com.hl.findining.menu

import com.hl.findining.shared.domain.enums.MenuCategory
import java.time.Instant

/**
 * 메뉴 도메인 엔티티 (API - 외부 모듈에서 접근 가능)
 */
data class Menu(
    val id: String? = null,
    val restaurantId: String,

    // 기본 정보
    val name: String,
    val description: String? = null,
    val price: Int,

    // 분류
    val category: MenuCategory = MenuCategory.MAIN,

    // 특성 플래그
    val isSignature: Boolean = false,      // 시그니처 메뉴 (대표메뉴)
    val isRecommended: Boolean = false,    // 추천 메뉴
    val isPopular: Boolean = false,        // 인기 메뉴 (리뷰 언급 기반)

    // 이미지
    val imageUrl: String? = null,

    // 메타데이터
    val createdAt: Instant = Instant.now()
) {
    /**
     * 임베딩 텍스트용 문자열 생성
     * 검색 인덱싱 시 사용
     */
    fun toEmbeddingText(): String {
        val parts = mutableListOf<String>()
        parts.add(name)

        if (isSignature) parts.add("시그니처")
        if (isRecommended) parts.add("추천")
        if (isPopular) parts.add("인기")

        return parts.joinToString(" ")
    }

    /**
     * 가격 정보를 포맷팅된 문자열로 반환
     */
    fun formattedPrice(): String =
        "${String.format("%,d", price)}원"
}

package com.hl.findining.shared.domain

import com.hl.findining.shared.domain.enums.TagCategory

/**
 * 식당에 연결된 태그 (비정규화된 형태)
 */
data class Tag(
    val id: String,                    // Tag ID
    val name: String,                  // 태그명
    val category: TagCategory,         // 카테고리
    val score: Double = 1.0            // 연관도 점수 (0.0 ~ 1.0)
) {
    init {
        require(score in 0.0..1.0) { "Score must be between 0.0 and 1.0" }
    }
}

