    DELIVERY("배달", listOf("배달", "배민", "요기요")),
    TAKEOUT("포장", listOf("포장", "테이크아웃", "투고")),
    PRIVATE_ROOM("룸", listOf("룸", "개인룸", "단체룸", "프라이빗")),
    PET_ALLOWED("반려동물", listOf("반려동물", "애견동반", "펫프렌들리")),
    NO_KIDS("노키즈존", listOf("노키즈", "노키즈존", "성인전용")),
