    val displayName: String,
    val minPrice: Int,
    val maxPrice: Int,
) {
    BUDGET("저가", 0, 10000),
    MODERATE("중가", 10000, 30000),
    EXPENSIVE("고가", 30000, 50000),
    PREMIUM("프리미엄", 50000, Int.MAX_VALUE),
    UNKNOWN("알수없음", 0, Int.MAX_VALUE),
    ;

    companion object {
        fun fromAveragePrice(price: Int): PriceRange = entries.first { price in it.minPrice until it.maxPrice }
    }
}

