package com.hl.findining.shared.domain

import java.time.DayOfWeek
import java.time.LocalTime

/**
 * 영업 시간 정보 (요일별 운영 시간, 브레이크타임, 라스트오더 포함)
 */
data class OperatingHour(
    val dayOfWeek: DayOfWeek,              // 요일
    val openTime: LocalTime?,              // 오픈 시간 (null이면 휴무)
    val closeTime: LocalTime?,             // 마감 시간
    val isOpen: Boolean = true,            // 영업 여부
    val breakStartTime: LocalTime? = null, // 브레이크타임 시작
    val breakEndTime: LocalTime? = null,   // 브레이크타임 종료
    val lastOrderTime: LocalTime? = null   // 라스트오더 시간
) {
    init {
        // 브레이크타임 유효성 검증
        require(breakStartTime == null || breakEndTime != null) {
            "브레이크 종료 시간이 설정되어야 합니다"
        }
        require(breakEndTime == null || breakStartTime != null) {
            "브레이크 시작 시간이 설정되어야 합니다"
        }
        if (breakStartTime != null && breakEndTime != null) {
            require(breakStartTime < breakEndTime) {
                "브레이크 시작 시간은 종료 시간보다 이전이어야 합니다"
            }
        }
        // 라스트오더 유효성 검증
        if (lastOrderTime != null && closeTime != null) {
            require(lastOrderTime <= closeTime) {
                "라스트오더는 마감 시간 이전이어야 합니다"
            }
        }
    }

    /**
     * 특정 시간에 영업중인지 확인 (브레이크타임 고려)
     */
    fun isOpenAt(time: LocalTime): Boolean {
        if (!isOpen || openTime == null || closeTime == null) return false

        val withinOperatingHours = if (closeTime > openTime) {
            // 일반적인 경우 (예: 11:00 ~ 22:00)
            time in openTime..closeTime
        } else {
            // 자정을 넘기는 경우 (예: 18:00 ~ 02:00)
            time >= openTime || time <= closeTime
        }

        if (!withinOperatingHours) return false

        // 브레이크타임 체크
        if (breakStartTime != null && breakEndTime != null) {
            if (time in breakStartTime..breakEndTime) {
                return false
            }
        }

        return true
    }

    /**
     * 특정 시간에 주문 가능한지 확인 (라스트오더 고려)
     */
    fun canOrderAt(time: LocalTime): Boolean {
        if (!isOpenAt(time)) return false
        return lastOrderTime?.let { time <= it } ?: true
    }

    /**
     * 브레이크타임 문자열 반환 (예: "15:00-17:00")
     */
    fun getBreakTimeString(): String? {
        return if (breakStartTime != null && breakEndTime != null) {
            "$breakStartTime-$breakEndTime"
        } else null
    }

    companion object {
        fun closed(dayOfWeek: DayOfWeek) = OperatingHour(
            dayOfWeek = dayOfWeek,
            openTime = null,
            closeTime = null,
            isOpen = false
        )
    }
}

package com.hl.findining.shared.domain

/**
 * 식당 통계 정보 (비정규화된 형태)
 */
data class Statistics(
    val rating: Double = 0.0,          // 평균 평점 (0.0 ~ 5.0)
    val reviewCount: Int = 0,          // 리뷰 수
    val bookmarkCount: Int = 0         // 북마크 수
) {
    val hasReviews: Boolean get() = reviewCount > 0

    fun withNewReview(newRating: Double): Statistics {
        val totalRating = rating * reviewCount + newRating
        val newCount = reviewCount + 1
        return copy(
            rating = totalRating / newCount,
            reviewCount = newCount
        )
    }

    fun withBookmark(added: Boolean): Statistics =
        copy(bookmarkCount = if (added) bookmarkCount + 1 else maxOf(0, bookmarkCount - 1))
}

package com.hl.findining.review

import com.hl.findining.shared.domain.enums.Sentiment
import java.time.Instant

/**
 * 리뷰 AI 분석 결과 Value Object
 * - 감성 분석, 태그 추출, 하이라이트 등 AI 분석 결과를 캡슐화
 */
data class ReviewAiAnalysis(
    val sentiment: Sentiment,                           // 감성 분석 결과
    val sentimentScore: Double,                         // 감성 점수 (0.0 ~ 1.0, 1.0이 가장 강한 감성)
    val extractedTags: List<ExtractedReviewTag>,        // 추출된 태그 목록
    val highlights: List<ReviewHighlight>,              // 주요 문장/구문 하이라이트
    val analyzedAt: Instant = Instant.now(),            // 분석 시점
    val modelVersion: String = "v1"                     // AI 모델 버전
) {
    init {
        require(sentimentScore in 0.0..1.0) { "Sentiment score must be between 0.0 and 1.0" }
    }

    /**
     * 고신뢰도 태그만 필터링
     */
    val highConfidenceTags: List<ExtractedReviewTag>
        get() = extractedTags.filter { it.isHighConfidence }

    /**
     * 긍정적 분석 결과인지 확인
     */
    val isPositive: Boolean get() = sentiment == Sentiment.POSITIVE

    /**
     * 부정적 분석 결과인지 확인
     */
    val isNegative: Boolean get() = sentiment == Sentiment.NEGATIVE

    /**
     * 중립적 분석 결과인지 확인
     */
    val isNeutral: Boolean get() = sentiment == Sentiment.NEUTRAL

    /**
     * 강한 감성인지 확인 (임계값: 0.7)
     */
    val hasStrongSentiment: Boolean get() = sentimentScore >= 0.7

    /**
     * 카테고리별 태그 그룹화
     */
    fun getTagsByCategory(): Map<String, List<ExtractedReviewTag>> {
        return extractedTags.groupBy { it.category.name }
    }

    /**
     * 상위 N개 태그 반환 (신뢰도 순)
     */
    fun getTopTags(n: Int = 5): List<ExtractedReviewTag> {
        return extractedTags.sortedByDescending { it.confidence }.take(n)
    }

    /**
     * 긍정/부정 하이라이트 분리
     */
    val positiveHighlights: List<ReviewHighlight>
        get() = highlights.filter { it.sentiment == Sentiment.POSITIVE }

    val negativeHighlights: List<ReviewHighlight>
        get() = highlights.filter { it.sentiment == Sentiment.NEGATIVE }

    companion object {
        /**
         * 분석되지 않은 상태를 나타내는 빈 분석 결과
         */
        fun empty(): ReviewAiAnalysis? = null

        /**
         * 기존 필드에서 마이그레이션 (하위 호환성)
         */
        fun fromLegacyFields(
            sentiment: Sentiment?,
            sentimentScore: Double?,
            extractedTags: List<String>,
            highlights: List<String>
        ): ReviewAiAnalysis? {
            if (sentiment == null) return null

            return ReviewAiAnalysis(
                sentiment = sentiment,
                sentimentScore = sentimentScore ?: 0.5,
                extractedTags = extractedTags.map { ExtractedReviewTag.fromString(it) },
                highlights = highlights.map { ReviewHighlight.fromText(it) },
                modelVersion = "legacy"
            )
        }
    }
}

/**
 * 리뷰 하이라이트 (주요 문장/구문)
 */
data class ReviewHighlight(
    val text: String,                                   // 하이라이트 텍스트
    val sentiment: Sentiment = Sentiment.NEUTRAL,       // 해당 문장의 감성
    val confidence: Double = 0.5,                       // 신뢰도
    val startIndex: Int? = null,                        // 원본 텍스트에서의 시작 위치
    val endIndex: Int? = null                           // 원본 텍스트에서의 끝 위치
) {
    init {
        require(text.isNotBlank()) { "Highlight text must not be blank" }
        require(confidence in 0.0..1.0) { "Confidence must be between 0.0 and 1.0" }
    }

    companion object {
        /**
         * 텍스트에서 기본 하이라이트 생성
         */
        fun fromText(text: String, sentiment: Sentiment = Sentiment.NEUTRAL): ReviewHighlight {
            return ReviewHighlight(
                text = text,
                sentiment = sentiment,
                confidence = 0.5
            )
        }
    }
}

package com.hl.findining.review

import com.hl.findining.shared.domain.enums.TagCategory

/**
 * AI가 리뷰에서 추출한 태그 Value Object
 * - 단순 문자열이 아닌 신뢰도 점수와 카테고리를 포함
 */
data class ExtractedReviewTag(
    val name: String,                           // 태그명 (예: "가성비", "회식", "데이트")
    val category: TagCategory,                  // 태그 카테고리
    val confidence: Double,                     // AI 신뢰도 점수 (0.0 ~ 1.0)
    val mentionCount: Int = 1,                  // 리뷰 내 언급 횟수
    val sourceText: String? = null              // 태그 추출 근거 텍스트
) {
    init {
        require(confidence in 0.0..1.0) { "Confidence must be between 0.0 and 1.0" }
        require(name.isNotBlank()) { "Tag name must not be blank" }
        require(mentionCount >= 1) { "Mention count must be at least 1" }
    }

    /**
     * 신뢰도가 높은 태그인지 확인 (임계값: 0.7)
     */
    val isHighConfidence: Boolean get() = confidence >= 0.7

    /**
     * 신뢰도가 낮은 태그인지 확인 (임계값: 0.4)
     */
    val isLowConfidence: Boolean get() = confidence < 0.4

    companion object {
        const val HIGH_CONFIDENCE_THRESHOLD = 0.7
        const val LOW_CONFIDENCE_THRESHOLD = 0.4

        /**
         * 단순 문자열에서 기본 태그 생성 (마이그레이션 용도)
         */
        fun fromString(tagName: String, category: TagCategory = TagCategory.FEATURE): ExtractedReviewTag {
            return ExtractedReviewTag(
                name = tagName,
                category = category,
                confidence = 0.5,  // 기본 신뢰도
                mentionCount = 1
            )
        }
    }
}

package com.hl.findining.review

import com.hl.findining.shared.domain.enums.TagCategory

/**
 * 식당 태그 Value Object (하이브리드 구조)
 * - category가 null이면 자유형 태그 (족발맛집, 고기질좋음 등)
 * - category가 있으면 분류형 태그 (가성비→FEATURE, 회식→OCCASION 등)
 */
data class RestaurantTag(
    val name: String,                           // 태그명 (예: "25인 이상", "가성비", "족발맛집")
    val category: TagCategory? = null,          // 태그 카테고리 (null = 자유형)
    val confidence: Double = 0.8                // AI 신뢰도 점수 (0.0 ~ 1.0)
) {
    init {
        require(confidence in 0.0..1.0) { "Confidence must be between 0.0 and 1.0" }
        require(name.isNotBlank()) { "Tag name must not be blank" }
    }

    /**
     * 카테고리가 지정된 태그인지 확인
     */
    val isCategorized: Boolean get() = category != null

    /**
     * 자유형 태그인지 확인
     */
    val isFreeForm: Boolean get() = category == null

    /**
     * 신뢰도가 높은 태그인지 확인 (임계값: 0.7)
     */
    val isHighConfidence: Boolean get() = confidence >= HIGH_CONFIDENCE_THRESHOLD

    /**
     * 신뢰도가 낮은 태그인지 확인 (임계값: 0.5)
     */
    val isLowConfidence: Boolean get() = confidence < LOW_CONFIDENCE_THRESHOLD

    companion object {
        const val HIGH_CONFIDENCE_THRESHOLD = 0.7
        const val LOW_CONFIDENCE_THRESHOLD = 0.5

        /**
         * 카테고리가 있는 태그 생성
         */
        fun categorized(name: String, category: TagCategory, confidence: Double = 0.8): RestaurantTag {
            return RestaurantTag(name = name, category = category, confidence = confidence)
        }

        /**
         * 자유형 태그 생성
         */
        fun freeForm(name: String, confidence: Double = 0.8): RestaurantTag {
            return RestaurantTag(name = name, category = null, confidence = confidence)
        }

        /**
         * 기존 ExtractedReviewTag에서 마이그레이션
         */
        fun fromExtractedTag(tag: ExtractedReviewTag): RestaurantTag {
            return RestaurantTag(
                name = tag.name,
                category = tag.category,
                confidence = tag.confidence
            )
        }
    }
}

package com.hl.findining.review

import com.hl.findining.shared.domain.enums.Sentiment
import java.time.Instant

/**
 * AI 생성 리뷰 요약 엔티티 (API - 외부 모듈에서 접근 가능)
 * - 식당별 리뷰 통합 요약 정보
 * - 영속성을 위한 id 필드 포함
 */
data class ReviewSummary(
    val id: String? = null,                           // Summary ID (영속성용)
    val restaurantId: String,                         // 식당 ID
    val summary: String,                              // AI 1줄 요약
    val topTags: List<ExtractedReviewTag>,            // 상위 태그 (빈도순, 타입 강화)
    val overallSentiment: Sentiment,                  // 전체적인 감성
    val sentimentDistribution: SentimentDistribution, // 감성 분포
    val positiveHighlights: List<ReviewHighlight>,    // 긍정적 포인트 (타입 강화)
    val negativeHighlights: List<ReviewHighlight>,    // 부정적 포인트 (타입 강화)
    val reviewCount: Int,                             // 분석된 리뷰 수
    val averageRating: Double,                        // 평균 평점
    val modelVersion: String = "v1",                  // AI 모델 버전
    val generatedAt: Instant = Instant.now(),         // 생성 시점
    val expiresAt: Instant? = null                    // 만료 시점 (캐시 용도)
) {
    /**
     * 요약이 만료되었는지 확인
     */
    val isExpired: Boolean
        get() = expiresAt?.isBefore(Instant.now()) ?: false

    /**
     * 긍정 비율 계산
     */
    val positiveRatio: Double
        get() = if (reviewCount > 0) {
            sentimentDistribution.positiveCount.toDouble() / reviewCount
        } else 0.0

    /**
     * 태그명 목록만 추출 (하위 호환성)
     */
    val topTagNames: List<String>
        get() = topTags.map { it.name }

    /**
     * 하이라이트 텍스트만 추출 (하위 호환성)
     */
    val positiveHighlightTexts: List<String>
        get() = positiveHighlights.map { it.text }

    val negativeHighlightTexts: List<String>
        get() = negativeHighlights.map { it.text }

    companion object {
        /**
         * 기존 형식에서 마이그레이션 (하위 호환성)
         */
        fun fromLegacy(
            restaurantId: String,
            summary: String,
            topTags: List<String>,
            overallSentiment: Sentiment,
            positiveHighlights: List<String>,
            negativeHighlights: List<String>,
            reviewCount: Int
        ): ReviewSummary {
            return ReviewSummary(
                restaurantId = restaurantId,
                summary = summary,
                topTags = topTags.map { ExtractedReviewTag.fromString(it) },
                overallSentiment = overallSentiment,
                sentimentDistribution = SentimentDistribution(
                    positiveCount = 0,
                    neutralCount = 0,
                    negativeCount = 0
                ),
                positiveHighlights = positiveHighlights.map { ReviewHighlight.fromText(it, Sentiment.POSITIVE) },
                negativeHighlights = negativeHighlights.map { ReviewHighlight.fromText(it, Sentiment.NEGATIVE) },
                reviewCount = reviewCount,
                averageRating = 0.0,
                modelVersion = "legacy"
            )
        }
    }
}

/**
 * 감성 분포 Value Object
 */
data class SentimentDistribution(
    val positiveCount: Int,
    val neutralCount: Int,
    val negativeCount: Int
) {
    init {
        require(positiveCount >= 0) { "Positive count must be non-negative" }
        require(neutralCount >= 0) { "Neutral count must be non-negative" }
        require(negativeCount >= 0) { "Negative count must be non-negative" }
    }

    val total: Int get() = positiveCount + neutralCount + negativeCount

    val positiveRatio: Double get() = if (total > 0) positiveCount.toDouble() / total else 0.0
    val neutralRatio: Double get() = if (total > 0) neutralCount.toDouble() / total else 0.0
    val negativeRatio: Double get() = if (total > 0) negativeCount.toDouble() / total else 0.0

    /**
     * 지배적인 감성 반환
     */
    val dominantSentiment: Sentiment
        get() = when {
            positiveCount >= neutralCount && positiveCount >= negativeCount -> Sentiment.POSITIVE
            negativeCount >= neutralCount && negativeCount >= positiveCount -> Sentiment.NEGATIVE
            else -> Sentiment.NEUTRAL
        }
}

