 * 식당 응답 (상세)
 */
data class RestaurantResponse(
    val id: String,
    val name: String,
    val nameEnglish: String?,
    val description: String?,
    val address: AddressResponse,
    val location: LocationResponse,
    val phone: String?,
    val website: String?,
    val cuisineTypes: List<String>,
    val priceRange: String,
    val averagePrice: Int?,
    val operatingHours: List<OperatingHourResponse>,
    val holidays: List<String>,
    val capacity: CapacityResponse?,
    val facilities: List<String>,
    val parkingInfo: String?,
    val aiSummary: String?,
    val tags: List<TagResponse>,
    val stats: StatisticsResponse,
    val status: String,
    val createdAt: Instant,
    val updatedAt: Instant
) {
    companion object {
        fun from(restaurant: Restaurant) = RestaurantResponse(
            id = restaurant.id ?: "",
            name = restaurant.name,
            nameEnglish = restaurant.nameEnglish,
            description = restaurant.description,
            address = AddressResponse.from(restaurant.address),
            location = LocationResponse.from(restaurant.location),
            phone = restaurant.phone,
            website = restaurant.website,
            cuisineTypes = restaurant.cuisineTypes.map { it.displayName },
            priceRange = restaurant.priceRange.name,
            averagePrice = restaurant.averagePrice,
            operatingHours = restaurant.operatingHours.map { OperatingHourResponse.from(it) },
            holidays = restaurant.holidays,
            capacity = restaurant.capacity?.let { CapacityResponse.from(it) },
            facilities = restaurant.facilities.map { it.displayName },
            parkingInfo = restaurant.parkingInfo,
            aiSummary = restaurant.aiSummary,
            tags = restaurant.tags.map { TagResponse.from(it) },
            stats = StatisticsResponse.from(restaurant.stats),
            status = restaurant.status.name,
            createdAt = restaurant.createdAt,
            updatedAt = restaurant.updatedAt
        )
    }
}

