data class OperatingHourResponse(
    val dayOfWeek: Int,
    val dayName: String,
    val openTime: String?,
    val closeTime: String?,
    val isOpen: Boolean,
    val breakStartTime: String?,
    val breakEndTime: String?,
    val lastOrderTime: String?,
    val breakTime: String?  // 편의용: "15:00-17:00" 형식
) {
    companion object {
        private val DAY_NAMES = mapOf(
            java.time.DayOfWeek.MONDAY to "월요일",
            java.time.DayOfWeek.TUESDAY to "화요일",
            java.time.DayOfWeek.WEDNESDAY to "수요일",
            java.time.DayOfWeek.THURSDAY to "목요일",
            java.time.DayOfWeek.FRIDAY to "금요일",
            java.time.DayOfWeek.SATURDAY to "토요일",
            java.time.DayOfWeek.SUNDAY to "일요일"
        )

        fun from(operatingHour: OperatingHour) = OperatingHourResponse(
            dayOfWeek = operatingHour.dayOfWeek.value,
            dayName = DAY_NAMES[operatingHour.dayOfWeek] ?: "",
            openTime = operatingHour.openTime?.toString(),
            closeTime = operatingHour.closeTime?.toString(),
            isOpen = operatingHour.isOpen,
            breakStartTime = operatingHour.breakStartTime?.toString(),
            breakEndTime = operatingHour.breakEndTime?.toString(),
            lastOrderTime = operatingHour.lastOrderTime?.toString(),
            breakTime = operatingHour.getBreakTimeString()
        )
    }
}

