package com.hl.findining.review.dto

import com.hl.findining.review.*
import com.hl.findining.shared.domain.enums.VisitType
import jakarta.validation.constraints.NotBlank
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Size
import java.time.Instant
import java.time.LocalDate

// ==================== Request DTOs ====================

/**
 * 리뷰 생성 요청
 */
data class CreateReviewRequest(
    @field:NotBlank(message = "식당 ID는 필수입니다")
    val restaurantId: String,

    @field:NotBlank(message = "작성자 이름은 필수입니다")
    @field:Size(max = 50, message = "작성자 이름은 50자 이하여야 합니다")
    val authorName: String,

    @field:NotBlank(message = "리뷰 내용은 필수입니다")
    @field:Size(min = 10, max = 2000, message = "리뷰 내용은 10자 이상 2000자 이하여야 합니다")
    val content: String,

    @field:NotNull(message = "평점은 필수입니다")
    val rating: Double,

    val visitDate: LocalDate? = null,
    val visitType: VisitType? = null,
    val images: List<ReviewImageRequest> = emptyList(),
    val source: ReviewSource = ReviewSource.INTERNAL
) {
    init {
        require(rating in 1.0..5.0) { "평점은 1.0에서 5.0 사이여야 합니다" }
    }

    fun toDomain(): Review = Review(
        restaurantId = restaurantId,
        authorName = authorName,
        authorSource = source,
        content = content,
        rating = rating,
        visitDate = visitDate,
        visitType = visitType,
        images = images.map { it.toDomain() },
        status = ReviewStatus.ACTIVE
    )
}

/**
 * 리뷰 수정 요청
 */
data class UpdateReviewRequest(
    @field:Size(min = 10, max = 2000, message = "리뷰 내용은 10자 이상 2000자 이하여야 합니다")
    val content: String? = null,

    val rating: Double? = null,
    val visitDate: LocalDate? = null,
    val visitType: VisitType? = null,
    val images: List<ReviewImageRequest>? = null,
    val status: ReviewStatus? = null
) {
    init {
        rating?.let { require(it in 1.0..5.0) { "평점은 1.0에서 5.0 사이여야 합니다" } }
    }

    fun applyTo(existing: Review): Review = existing.copy(
        content = content ?: existing.content,
        rating = rating ?: existing.rating,
        visitDate = visitDate ?: existing.visitDate,
        visitType = visitType ?: existing.visitType,
        images = images?.map { it.toDomain() } ?: existing.images,
        status = status ?: existing.status,
        updatedAt = Instant.now()
    )
}

data class ReviewImageRequest(
    @field:NotBlank(message = "이미지 URL은 필수입니다")
    val url: String,
    val thumbnailUrl: String? = null,
    val caption: String? = null
) {
    fun toDomain() = ReviewImage(
        url = url,
        thumbnailUrl = thumbnailUrl,
        caption = caption
    )
}

// ==================== Response DTOs ====================

/**
 * 리뷰 응답 (상세)
 */
