import com.hl.findining.shared.domain.enums.Sentiment
import com.hl.findining.shared.domain.enums.TagCategory
import jakarta.validation.constraints.NotBlank
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Size
import java.time.Instant

// ==================== Request DTOs ====================

/**
 * 리뷰 요약 생성 요청
 */
data class CreateReviewSummaryRequest(
    @field:NotBlank(message = "식당 ID는 필수입니다")
    val restaurantId: String,

    @field:NotBlank(message = "요약 내용은 필수입니다")
    @field:Size(max = 500, message = "요약은 500자 이하여야 합니다")
    val summary: String,

    @field:NotNull(message = "태그 목록은 필수입니다")
    val tags: List<RestaurantTagRequest>,

    @field:NotNull(message = "전체 감성은 필수입니다")
    val overallSentiment: Sentiment,

    val positiveHighlights: List<String> = emptyList(),
    val negativeHighlights: List<String> = emptyList(),
    val reviewCount: Int = 0,
    val averageRating: Double = 0.0
) {
    fun toDomain(): ReviewSummaryV2 = ReviewSummaryV2(
        restaurantId = restaurantId,
        summary = summary,
        tags = tags.map { it.toDomain() },
        overallSentiment = overallSentiment,
        positiveHighlights = positiveHighlights,
        negativeHighlights = negativeHighlights,
        reviewCount = reviewCount,
        averageRating = averageRating.coerceIn(0.0, 5.0)
    )
}

/**
 * 리뷰 요약 수정 요청
 */
data class UpdateReviewSummaryRequest(
    @field:Size(max = 500, message = "요약은 500자 이하여야 합니다")
    val summary: String? = null,

    val tags: List<RestaurantTagRequest>? = null,
    val overallSentiment: Sentiment? = null,
    val positiveHighlights: List<String>? = null,
    val negativeHighlights: List<String>? = null,
    val reviewCount: Int? = null,
    val averageRating: Double? = null
) {
    fun applyTo(existing: ReviewSummaryV2): ReviewSummaryV2 = existing.copy(
        summary = summary ?: existing.summary,
        tags = tags?.map { it.toDomain() } ?: existing.tags,
        overallSentiment = overallSentiment ?: existing.overallSentiment,
        positiveHighlights = positiveHighlights ?: existing.positiveHighlights,
        negativeHighlights = negativeHighlights ?: existing.negativeHighlights,
        reviewCount = reviewCount ?: existing.reviewCount,
        averageRating = averageRating?.coerceIn(0.0, 5.0) ?: existing.averageRating
    )
}

/**
 * 식당 태그 요청
