    val restaurantId: String,
    val summary: String,
    val tagNames: List<String>,
    val overallSentiment: String,
    val reviewCount: Int,
    val averageRating: Double
) {
    companion object {
        fun from(summary: ReviewSummaryV2): ReviewSummaryV2BriefResponse = ReviewSummaryV2BriefResponse(
            restaurantId = summary.restaurantId,
            summary = if (summary.summary.length > 100) summary.summary.take(100) + "..." else summary.summary,
            tagNames = summary.tagNames.take(5),
            overallSentiment = summary.overallSentiment.name,
            reviewCount = summary.reviewCount,
            averageRating = summary.averageRating
        )
    }
}

/**
 * 식당 태그 응답
 */
data class RestaurantTagResponse(
    val name: String,
    val category: String?,
    val confidence: Double,
    val isHighConfidence: Boolean
) {
    companion object {
        fun from(tag: RestaurantTag): RestaurantTagResponse = RestaurantTagResponse(
            name = tag.name,
            category = tag.category?.name,
            confidence = tag.confidence,
            isHighConfidence = tag.isHighConfidence
        )
    }
}

/**
 * 여러 식당 요약 일괄 조회 응답
 */
data class BulkReviewSummaryResponse(
    val summaries: Map<String, ReviewSummaryV2Response>,
    val missingRestaurantIds: List<String>
) {
    companion object {
        fun from(
            summaries: Map<String, ReviewSummaryV2>,
            requestedIds: List<String>
        ): BulkReviewSummaryResponse {
            val responseMap = summaries.mapValues { ReviewSummaryV2Response.from(it.value) }
            val missingIds = requestedIds.filter { it !in summaries.keys }
            return BulkReviewSummaryResponse(
                summaries = responseMap,
                missingRestaurantIds = missingIds
            )
        }
    }
}

package com.hl.findining.menu

import com.hl.findining.menu.dto.*
import com.hl.findining.shared.domain.enums.MenuCategory
import com.hl.findining.shared.dto.ApiResponse
import com.hl.findining.shared.exception.ResourceNotFoundException
import jakarta.validation.Valid
import org.slf4j.LoggerFactory
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.*

/**
 * 메뉴 REST API
 */
@RestController
@RequestMapping("/api/v1/menus")
class MenuController(
    private val menuService: MenuService
) {
    private val logger = LoggerFactory.getLogger(javaClass)

    /**
     * 메뉴 상세 조회
     *
     * GET /api/v1/menus/{id}
     */
    @GetMapping("/{id}")
    fun getMenu(@PathVariable id: String): ResponseEntity<ApiResponse<MenuResponse>> {
        logger.debug("Get menu: id=$id")

        val menu = menuService.getById(id)
            ?: throw ResourceNotFoundException("Menu", id)

        return ResponseEntity.ok(ApiResponse.success(MenuResponse.from(menu)))
    }

    /**
     * 식당별 전체 메뉴 조회 (카테고리별 그룹)
     *
     * GET /api/v1/menus/restaurant/{restaurantId}
     */
    @GetMapping("/restaurant/{restaurantId}")
    fun getMenusByRestaurant(
        @PathVariable restaurantId: String
    ): ResponseEntity<ApiResponse<RestaurantMenusResponse>> {
        logger.debug("Get menus for restaurant: restaurantId=$restaurantId")

        val menus = menuService.findByRestaurantId(restaurantId)
        val response = RestaurantMenusResponse.from(restaurantId, menus)

        return ResponseEntity.ok(ApiResponse.success(response))
    }

    /**
     * 식당별 시그니처 메뉴 조회
     *
     * GET /api/v1/menus/restaurant/{restaurantId}/signature
     */
    @GetMapping("/restaurant/{restaurantId}/signature")
    fun getSignatureMenus(
        @PathVariable restaurantId: String
    ): ResponseEntity<ApiResponse<List<MenuSummaryResponse>>> {
        logger.debug("Get signature menus for restaurant: restaurantId=$restaurantId")

        val menus = menuService.findSignatureMenus(restaurantId)
        val response = menus.map { MenuSummaryResponse.from(it) }

        return ResponseEntity.ok(ApiResponse.success(response))
    }

    /**
     * 식당별 추천 메뉴 조회
     *
     * GET /api/v1/menus/restaurant/{restaurantId}/recommended
     */
    @GetMapping("/restaurant/{restaurantId}/recommended")
    fun getRecommendedMenus(
        @PathVariable restaurantId: String
    ): ResponseEntity<ApiResponse<List<MenuSummaryResponse>>> {
        logger.debug("Get recommended menus for restaurant: restaurantId=$restaurantId")

        val menus = menuService.findRecommendedMenus(restaurantId)
        val response = menus.map { MenuSummaryResponse.from(it) }

        return ResponseEntity.ok(ApiResponse.success(response))
    }

    /**
     * 식당별 인기 메뉴 조회 (리뷰 언급 기반)
     *
     * GET /api/v1/menus/restaurant/{restaurantId}/popular?limit=5
     */
    @GetMapping("/restaurant/{restaurantId}/popular")
    fun getPopularMenus(
        @PathVariable restaurantId: String,
        @RequestParam(defaultValue = "5") limit: Int
    ): ResponseEntity<ApiResponse<List<MenuSummaryResponse>>> {
        logger.debug("Get popular menus for restaurant: restaurantId=$restaurantId, limit=$limit")

        val menus = menuService.findPopularMenus(restaurantId, limit.coerceIn(1, 20))
        val response = menus.map { MenuSummaryResponse.from(it) }

        return ResponseEntity.ok(ApiResponse.success(response))
    }

    /**
     * 식당별 카테고리별 메뉴 조회
     *
     * GET /api/v1/menus/restaurant/{restaurantId}/category/{category}
     */
    @GetMapping("/restaurant/{restaurantId}/category/{category}")
    fun getMenusByCategory(
        @PathVariable restaurantId: String,
        @PathVariable category: MenuCategory
    ): ResponseEntity<ApiResponse<List<MenuSummaryResponse>>> {
        logger.debug("Get menus by category: restaurantId=$restaurantId, category=$category")

        val menus = menuService.findByCategory(restaurantId, category)
        val response = menus.map { MenuSummaryResponse.from(it) }

        return ResponseEntity.ok(ApiResponse.success(response))
    }

    /**
     * 메뉴 생성
     *
     * POST /api/v1/menus
     */
    @PostMapping
    fun createMenu(
        @Valid @RequestBody request: CreateMenuRequest
    ): ResponseEntity<ApiResponse<MenuResponse>> {
        logger.info("Create menu: name=${request.name}, restaurantId=${request.restaurantId}")

        val menu = request.toDomain()
        val saved = menuService.save(menu)

        return ResponseEntity
            .status(HttpStatus.CREATED)
            .body(ApiResponse.success(MenuResponse.from(saved)))
    }

    /**
     * 메뉴 벌크 생성 (크롤링용)
     *
     * POST /api/v1/menus/bulk
     */
    @PostMapping("/bulk")
    fun bulkCreateMenus(
        @Valid @RequestBody request: BulkCreateMenuRequest
    ): ResponseEntity<ApiResponse<BulkCreateMenuResponse>> {
        logger.info("Bulk create menus: restaurantId=${request.restaurantId}, count=${request.menus.size}")

        // 기존 메뉴 삭제 옵션
        if (request.replaceExisting) {
            menuService.deleteByRestaurantId(request.restaurantId)
        }

        val menus = request.menus.map { menuItem ->
            menuItem.toDomain(request.restaurantId)
        }

        val saved = menuService.saveAll(menus)

        return ResponseEntity
            .status(HttpStatus.CREATED)
            .body(
                ApiResponse.success(
                    BulkCreateMenuResponse(
                        restaurantId = request.restaurantId,
                        createdCount = saved.size,
                        menuIds = saved.mapNotNull { it.id }
                    )
                )
            )
    }

    /**
     * 메뉴 수정
     *
     * PUT /api/v1/menus/{id}
     */
    @PutMapping("/{id}")
    fun updateMenu(
        @PathVariable id: String,
        @Valid @RequestBody request: UpdateMenuRequest
    ): ResponseEntity<ApiResponse<MenuResponse>> {
        logger.info("Update menu: id=$id")

        val existing = menuService.getById(id)
            ?: throw ResourceNotFoundException("Menu", id)

        val updated = request.applyTo(existing)
        val saved = menuService.save(updated)

        return ResponseEntity.ok(ApiResponse.success(MenuResponse.from(saved)))
    }

    /**
     * 메뉴 삭제
     *
     * DELETE /api/v1/menus/{id}
     */
    @DeleteMapping("/{id}")
    fun deleteMenu(@PathVariable id: String): ResponseEntity<ApiResponse<Unit>> {
        logger.info("Delete menu: id=$id")

        menuService.getById(id)
            ?: throw ResourceNotFoundException("Menu", id)

        menuService.delete(id)

        return ResponseEntity.ok(ApiResponse.success(Unit))
    }

    /**
     * 가격 범위로 메뉴 검색
     *
     * GET /api/v1/menus/restaurant/{restaurantId}/price-range?minPrice=10000&maxPrice=30000
     */
    @GetMapping("/restaurant/{restaurantId}/price-range")
    fun getMenusByPriceRange(
        @PathVariable restaurantId: String,
        @RequestParam minPrice: Int,
        @RequestParam maxPrice: Int
    ): ResponseEntity<ApiResponse<List<MenuSummaryResponse>>> {
        logger.debug("Get menus by price range: restaurantId=$restaurantId, min=$minPrice, max=$maxPrice")

        val menus = menuService.findByPriceRange(restaurantId, minPrice, maxPrice)
        val response = menus.map { MenuSummaryResponse.from(it) }

        return ResponseEntity.ok(ApiResponse.success(response))
    }
}

