package com.hl.findining.search.embedding

import com.hl.findining.restaurant.Restaurant
import com.hl.findining.review.ReviewSummaryV2
import com.hl.findining.shared.domain.enums.Sentiment
import org.springframework.ai.document.Document
import org.springframework.stereotype.Component

/**
 * Spring AI Document 빌더
 * - Restaurant + ReviewSummaryV2 → Spring AI Document 변환
 * - VectorStore에 저장될 문서 형식 생성
 */
@Component
class RestaurantDocumentBuilder(
    private val textBuilder: RestaurantEmbeddingTextBuilder
) {

    companion object {
        private const val DOCUMENT_ID_PREFIX = "rest_"
    }

    /**
     * Restaurant + ReviewSummaryV2 + Menu → Spring AI Document
     *
     * Document 구조:
     * - id: "rest_{restaurantId}"
     * - text: 임베딩 텍스트 (시맨틱 검색용) - 메뉴 정보 포함
     * - metadata: 필터링용 메타데이터
     */
    fun build(
        restaurant: Restaurant,
        summary: ReviewSummaryV2?,
        menuEmbeddingText: String? = null
    ): Document {
        val embeddingText = textBuilder.build(restaurant, summary, menuEmbeddingText)
        val metadata = buildMetadata(restaurant, summary)

        return Document.builder()
            .id("$DOCUMENT_ID_PREFIX${restaurant.id}")
            .text(embeddingText)
            .metadata(metadata)
            .build()
    }

    /**
     * 벌크 빌드
     */
    fun buildAll(
        restaurants: List<Restaurant>,
        summaryMap: Map<String, ReviewSummaryV2>,
        menuTextMap: Map<String, String> = emptyMap()
    ): List<Document> {
        return restaurants.mapNotNull { restaurant ->
            restaurant.id?.let { id ->
                build(restaurant, summaryMap[id], menuTextMap[id])
            }
        }
    }

    /**
     * 필터링용 메타데이터 생성
     *
     * Spring AI Filter Expression 예시:
     * - priceRange == 'MODERATE' && maxCapacity >= 10
     * - hasPrivateRoom == true && sigungu == '강남구'
     * - tags CONTAINS '가성비'
     */
    private fun buildMetadata(
        restaurant: Restaurant,
        summary: ReviewSummaryV2?
    ): Map<String, Any> = buildMap {
        // 식별자
        put("restaurantId", restaurant.id ?: "")

        // 음식 종류 (필터링용 - 콤마 구분)
        put("cuisineTypes", restaurant.cuisineTypes.joinToString(",") { it.name })

        // 가격대
        put("priceRange", restaurant.priceRange.name)

        // 수용 인원
        put("maxCapacity", restaurant.capacity?.maxPeople ?: 0)

        // 개인룸 여부
        put("hasPrivateRoom", restaurant.hasPrivateRoom())

        // 시설 정보 (필터링용 - 콤마 구분)
        put("facilities", restaurant.facilities.joinToString(",") { it.name })

        // 위치 정보
        put("sigungu", restaurant.address.sigungu)
        restaurant.address.dong?.let { put("dong", it) }

        // 통계 정보
        put("rating", restaurant.stats.rating)
        put("reviewCount", restaurant.stats.reviewCount)

        // 감성 정보 (AI 요약 기반)
        put("sentiment", summary?.overallSentiment?.name ?: Sentiment.NEUTRAL.name)

        // AI 태그 (콤마 구분 - 검색 필터링용)
        put("tags", summary?.tagNames?.joinToString(",") ?: "")

        // 상태
        put("status", restaurant.status.name)
    }

    /**
     * Document ID에서 Restaurant ID 추출
     */
    fun extractRestaurantId(documentId: String): String? {
        return if (documentId.startsWith(DOCUMENT_ID_PREFIX)) {
            documentId.removePrefix(DOCUMENT_ID_PREFIX)
        } else {
            null
        }
    }
}

package com.hl.findining.search.embedding

import com.hl.findining.restaurant.Restaurant
import com.hl.findining.review.ReviewSummaryV2
import org.springframework.stereotype.Component

/**
 * 식당 임베딩 텍스트 생성기
 * - 시맨틱 검색을 위한 최적화된 텍스트 구조
 * - Google GenAI text-embedding-004 모델에 최적화
 */
@Component
class RestaurantEmbeddingTextBuilder {

    companion object {
        private const val MAX_SUMMARY_LENGTH = 100
        private const val MAX_HIGHLIGHTS = 3
    }

    /**
     * 임베딩용 텍스트 생성 (V3 - 메뉴 정보 포함)
     *
     * 구조 (섹션 마커 포함):
     * [식당] {name} {cuisineTypes}
     * [위치] {sigungu} {dong}
     * [메뉴] 대표: {signatureMenus} | 가격대: {priceRange}
     * [요약] {aiSummary}
     * [태그] {highConfidenceTags}
     * [장점] {positiveHighlights}
     *
     * 예시:
     * "[식당] 족발야시장 강남점 족발 보쌈 한식
     * [위치] 강남구 역삼동
     * [메뉴] 대표: 족발 시그니처, 막국수 인기, 보쌈 추천 | 가격대: 35,000~55,000원
     * [요약] 강남 직장인들에게 인기 있는 가성비 좋은 족발집으로 25명 이상 회식 가능
     * [태그] 가성비 회식 양많음 단체석
     * [장점] 족발이 부드러워요 막국수가 맛있어요 단체룸이 넓어요"
     */
    fun build(restaurant: Restaurant, summary: ReviewSummaryV2?, menuEmbeddingText: String? = null): String = buildString {
        // 기본 정보: 이름 + 음식 종류
        append("[식당] ")
        append(restaurant.name)
        if (restaurant.cuisineTypes.isNotEmpty()) {
            append(" ")
            append(restaurant.cuisineTypes.joinToString(" ") { it.displayName })
        }
        appendLine()

        // 위치 정보: 시군구 + 동
        append("[위치] ")
        append(restaurant.address.sigungu)
        restaurant.address.dong?.let { dong ->
            append(" ")
            append(dong)
        }

        // 메뉴 정보 (menuEmbeddingText가 있는 경우)
        menuEmbeddingText?.let { menuText ->
            if (menuText.isNotBlank()) {
                appendLine()
                append(menuText)  // MenuService.buildEmbeddingText()가 "[메뉴]" 포함해서 반환
            }
        }

        // AI 요약 (ReviewSummaryV2가 있는 경우)
        summary?.let { s ->
            // 요약 본문 (100자 제한)
            val summaryText = s.summary.take(MAX_SUMMARY_LENGTH)
            if (summaryText.isNotBlank()) {
                appendLine()
                append("[요약] ")
                append(summaryText)
            }

            // 태그 (고신뢰도 태그만 - V2 내장 프로퍼티 사용)
            val highConfidenceTags = s.highConfidenceTags
                .joinToString(" ") { it.name }
            if (highConfidenceTags.isNotBlank()) {
                appendLine()
                append("[태그] ")
                append(highConfidenceTags)
            }

            // 긍정적 하이라이트 (상위 3개 - V2는 List<String>)
            val highlights = s.positiveHighlights
                .take(MAX_HIGHLIGHTS)
                .joinToString(" ")
            if (highlights.isNotBlank()) {
                appendLine()
                append("[장점] ")
                append(highlights)
            }
        }
    }.trim()
}
